"""Exact money arithmetic."""
from decimal import Decimal, ROUND_HALF_UP, ROUND_DOWN


class CurrencyMismatch(Exception):
    pass


class Money:
    def __init__(self, amount, currency='USD'):
        self.currency = currency
        self.cents = int(
            (Decimal(str(amount)) * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
        )

    # --- helpers ---

    @classmethod
    def _from_cents(cls, cents, currency):
        obj = cls.__new__(cls)
        obj.currency = currency
        obj.cents = int(cents)
        return obj

    def _check_currency(self, other):
        if self.currency != other.currency:
            raise CurrencyMismatch(
                f"Cannot combine {self.currency} with {other.currency}"
            )

    # --- arithmetic ---

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return Money._from_cents(self.cents + other.cents, self.currency)

    def __sub__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return Money._from_cents(self.cents - other.cents, self.currency)

    def __mul__(self, other):
        if isinstance(other, Money):
            raise TypeError("Cannot multiply Money by Money")
        factor = Decimal(str(other))
        new_cents = int(
            (Decimal(self.cents) * factor).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
        )
        return Money._from_cents(new_cents, self.currency)

    def __rmul__(self, other):
        return self.__mul__(other)

    def __neg__(self):
        return Money._from_cents(-self.cents, self.currency)

    # --- comparison ---

    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return self.cents == other.cents and self.currency == other.currency

    def __lt__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return self.cents < other.cents

    def __hash__(self):
        return hash((self.cents, self.currency))

    # --- allocation ---

    def allocate(self, pairs):
        pairs = list(pairs)
        for key, weight in pairs:
            if weight <= 0:
                raise ValueError(f"Weight must be positive, got {weight}")

        if self.cents == 0:
            return {key: Money._from_cents(0, self.currency) for key, _ in pairs}

        total_weight = sum(Decimal(str(w)) for _, w in pairs)

        # Floor-based base allocations
        base = []
        for key, weight in pairs:
            b = int(
                (Decimal(self.cents) * Decimal(str(weight)) / total_weight).quantize(
                    Decimal('1'), rounding=ROUND_DOWN
                )
            )
            base.append(b)

        remainder = self.cents - sum(base)

        # Distribute leftover cents to largest weight first; ties broken by
        # original (earlier) key order.
        order = sorted(
            range(len(pairs)),
            key=lambda i: (-Decimal(str(pairs[i][1])), i),
        )
        for i in order:
            if remainder <= 0:
                break
            base[i] += 1
            remainder -= 1

        return {
            key: Money._from_cents(c, self.currency)
            for (key, _), c in zip(pairs, base)
        }

    # --- formatting ---

    def format(self):
        if self.cents < 0:
            abs_cents = -self.cents
            return f'-${abs_cents // 100}.{abs_cents % 100:02d}'
        return f'${self.cents // 100}.{self.cents % 100:02d}'

    def __repr__(self):
        return f"Money({self.cents / 100}, '{self.currency}')"
