"""Event-sourced aggregate."""
import copy


class InvalidEvent(Exception):
    pass


class Aggregate:
    def __init__(self):
        self.state = {'count': 0, 'total': 0}
        self.version = 0
        self.pending = []
        self._seen_seq = set()

    def handle(self, command):
        events = [
            {'name': 'added', 'amount': command.get('amount', 0), 'seq': self.version + 1}
        ]
        self.pending.extend(events)
        return events

    def apply(self, event):
        name = event.get('name')
        if name not in ('added',):
            raise InvalidEvent(name)
        seq = event.get('seq')
        if seq is not None and seq in self._seen_seq:
            raise InvalidEvent(f"duplicate seq {seq}")
        # All guards passed – safe to mutate.
        if name == 'added':
            self.state['count'] += 1
            self.state['total'] += event['amount']
        self.version += 1
        if seq is not None:
            self._seen_seq.add(seq)
        if event in self.pending:
            self.pending.remove(event)

    def rehydrate(self, events):
        for event in events:
            self.apply(event)
        return self

    def snapshot(self):
        return copy.deepcopy(self.state)
