"""Expression parser."""
import re


class ExprError(Exception):
    pass


_NUM_RE = re.compile(r'\d+\.?\d*|\.\d+')
_OP_RE = re.compile(r'\*\*|//|[+\-*/%()]')


def tokenize(text):
    if not text or not text.strip():
        raise ExprError("empty input")

    tokens = []
    i = 0
    text = text.strip()

    while i < len(text):
        if text[i].isspace():
            i += 1
            continue

        m = _NUM_RE.match(text, i)
        if m:
            val = m.group()
            if '.' in val:
                tokens.append(float(val))
            else:
                tokens.append(int(val))
            i = m.end()
            continue

        m = _OP_RE.match(text, i)
        if m:
            tokens.append(m.group())
            i = m.end()
            continue

        raise ExprError(f"bad token at position {i}")

    if not tokens:
        raise ExprError("empty input")

    return tokens


def parse(text):
    tokens = tokenize(text)
    parser = _Parser(tokens)
    result = parser.parse_expr()
    if parser.pos != len(tokens):
        raise ExprError("trailing junk")
    return result


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse_expr(self):
        left = self.parse_term()
        while self.peek() in ('+', '-'):
            op = self.consume()
            right = self.parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_term(self):
        left = self.parse_factor()
        while self.peek() in ('*', '/', '//', '%'):
            op = self.consume()
            right = self.parse_factor()
            if op == '*':
                left = left * right
            elif op == '/':
                if right == 0:
                    raise ExprError("division by zero")
                left = left / right
            elif op == '//':
                if right == 0:
                    raise ExprError("division by zero")
                left = left // right
            else:
                if right == 0:
                    raise ExprError("division by zero")
                left = left % right
        return left

    def parse_factor(self):
        tok = self.peek()
        if tok == '+':
            self.consume()
            return +self.parse_factor()
        if tok == '-':
            self.consume()
            return -self.parse_factor()
        return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        if self.peek() == '**':
            self.consume()
            exp = self.parse_factor()
            return base ** exp
        return base

    def parse_atom(self):
        tok = self.peek()
        if tok is None:
            raise ExprError("unexpected end of input")
        if isinstance(tok, (int, float)):
            self.consume()
            return tok
        if tok == '(':
            self.consume()
            val = self.parse_expr()
            if self.peek() != ')':
                raise ExprError("unbalanced parentheses")
            self.consume()
            return val
        raise ExprError(f"unexpected token: {tok}")
