"""Autocomplete trie."""


class _TrieNode:
    __slots__ = ("children", "is_end", "weight")

    def __init__(self):
        self.children = {}
        self.is_end = False
        self.weight = 0


class Trie:
    def __init__(self):
        self._root = _TrieNode()
        self._count = 0

    # ------------------------------------------------------------------
    # Insert / Remove
    # ------------------------------------------------------------------

    def insert(self, word, weight=1):
        word = word.lower()
        node = self._root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = _TrieNode()
            node = node.children[ch]
        if not node.is_end:
            self._count += 1
        node.is_end = True
        node.weight = weight

    def remove(self, word):
        word = word.lower()
        node = self._root
        path = []
        for ch in word:
            if ch not in node.children:
                return
            path.append((node, ch))
            node = node.children[ch]
        if not node.is_end:
            return
        node.is_end = False
        node.weight = 0
        self._count -= 1
        # Prune dead branches
        for parent, ch in reversed(path):
            child = parent.children[ch]
            if not child.is_end and not child.children:
                del parent.children[ch]
            else:
                break

    # ------------------------------------------------------------------
    # Completion
    # ------------------------------------------------------------------

    def complete(self, prefix, limit=10):
        prefix = prefix.lower()
        node = self._root
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]
        results = []
        self._collect(node, prefix, results)
        results.sort(key=lambda x: (-x[1], x[0]))
        if limit is None or limit == 0:
            return [w for w, _ in results]
        return [w for w, _ in results[:limit]]

    def _collect(self, node, prefix, results):
        if node.is_end:
            results.append((prefix, node.weight))
        for ch in sorted(node.children):
            self._collect(node.children[ch], prefix + ch, results)

    # ------------------------------------------------------------------
    # Weight update
    # ------------------------------------------------------------------

    def update_weight(self, word, delta):
        word = word.lower()
        node = self._root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = _TrieNode()
            node = node.children[ch]
        if not node.is_end:
            node.is_end = True
            node.weight = delta
            self._count += 1
        else:
            node.weight += delta

    # ------------------------------------------------------------------
    # Dunder helpers
    # ------------------------------------------------------------------

    def __contains__(self, word):
        word = word.lower()
        node = self._root
        for ch in word:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return node.is_end

    def __len__(self):
        return self._count

    # ------------------------------------------------------------------
    # Longest prefix of a text
    # ------------------------------------------------------------------

    def longest_prefix_of(self, text):
        text = text.lower()
        node = self._root
        longest = None
        current = ""
        for ch in text:
            if ch not in node.children:
                break
            node = node.children[ch]
            current += ch
            if node.is_end:
                longest = current
        return longest

    # ------------------------------------------------------------------
    # All words
    # ------------------------------------------------------------------

    def words(self):
        results = []
        self._collect_words(self._root, "", results)
        return sorted(results)

    def _collect_words(self, node, prefix, results):
        if node.is_end:
            results.append(prefix)
        for ch in sorted(node.children):
            self._collect_words(node.children[ch], prefix + ch, results)
