"""Batch processing."""
from dataclasses import dataclass


@dataclass
class BatchStats:
    processed: int = 0
    failed: int = 0


def chunked(source, size):
    if size <= 0:
        raise ValueError("size must be positive")
    chunk = []
    for item in source:
        chunk.append(item)
        if len(chunk) == size:
            yield chunk
            chunk = []
    if chunk:
        yield chunk


def run_batches(source, fn, size, on_error=None):
    results = []
    processed = 0
    failed = 0
    for chunk in chunked(source, size):
        try:
            result = fn(chunk)
            results.append(result)
            processed += 1
        except Exception as exc:
            results.append(None)
            failed += 1
            if on_error is not None:
                on_error(chunk, exc)
    return results, BatchStats(processed, failed)
