"""TTL cache - entries expire based on an injectable clock."""
import time


class Cache:
    def __init__(self, default_ttl=None, get_clock=None):
        self.default_ttl = default_ttl
        self._get_clock = get_clock if get_clock is not None else time.monotonic
        self._data = {}  # key -> (value, expiry)

    def put(self, key, value, ttl=None):
        if ttl is None:
            ttl = self.default_ttl
        if ttl is None:
            expiry = float("inf")
        else:
            expiry = self._get_clock() + ttl
        self._data[key] = (value, expiry)

    def get(self, key):
        if key not in self._data:
            return None
        value, expiry = self._data[key]
        if self._get_clock() >= expiry:
            del self._data[key]
            return None
        return value

    def get_or_set(self, key, factory, ttl=None):
        if key in self._data:
            value, expiry = self._data[key]
            if self._get_clock() < expiry:
                return value
            del self._data[key]
        value = factory()
        self.put(key, value, ttl)
        return value

    def delete(self, key):
        if key in self._data:
            del self._data[key]
            return True
        return False

    def __len__(self):
        now = self._get_clock()
        return sum(1 for _, expiry in self._data.values() if now < expiry)

    def __contains__(self, key):
        if key not in self._data:
            return False
        _, expiry = self._data[key]
        return self._get_clock() < expiry

    def purge(self):
        now = self._get_clock()
        expired = [k for k, (_, expiry) in self._data.items() if now >= expiry]
        for k in expired:
            del self._data[k]
        return len(expired)

    def keys(self):
        now = self._get_clock()
        return sorted(k for k, (_, expiry) in self._data.items() if now < expiry)
