"""Dependency graph."""


class Graph:
    def __init__(self):
        self._mods = {}

    def add_module(self, name, provides=(), requires=()):
        self._mods[name] = (set(provides), set(requires))

    def dependents(self, name):
        return sorted(mod for mod, (_, requires) in self._mods.items() if name in requires)

    def _resolve_start(self, name):
        if name in self._mods:
            return {name}
        return {mod for mod, (provides, _) in self._mods.items() if name in provides}

    def _module_dependents(self, mod_name):
        provides = self._mods[mod_name][0]
        result = set()
        for other, (_, requires) in self._mods.items():
            if other == mod_name:
                continue
            if mod_name in requires or requires & provides:
                result.add(other)
        return result

    def reverse_closure(self, name):
        start = self._resolve_start(name)
        visited = set()
        queue = list(start)
        while queue:
            mod = queue.pop()
            if mod in visited:
                continue
            visited.add(mod)
            for dep in self._module_dependents(mod):
                if dep not in visited:
                    queue.append(dep)
        return visited

    def invalidate(self, name):
        to_remove = self.reverse_closure(name)
        for mod in to_remove:
            del self._mods[mod]
        return to_remove

    def missing(self):
        all_provides = set()
        all_requires = set()
        for provides, requires in self._mods.values():
            all_provides |= provides
            all_requires |= requires
        return sorted(all_requires - all_provides)

    def cycles(self):
        adj = {mod: set() for mod in self._mods}
        for mod, (provides, requires) in self._mods.items():
            for other, (other_provides, _) in self._mods.items():
                if other == mod:
                    continue
                if other in requires or requires & other_provides:
                    adj[mod].add(other)

        all_cycles = set()

        def dfs(start, node, path, path_set):
            for neighbor in sorted(adj.get(node, set())):
                if neighbor == start:
                    all_cycles.add(tuple(sorted(path)))
                elif neighbor not in path_set and neighbor > start:
                    path.append(neighbor)
                    path_set.add(neighbor)
                    dfs(start, neighbor, path, path_set)
                    path.pop()
                    path_set.remove(neighbor)

        for start in sorted(self._mods.keys()):
            dfs(start, start, [start], {start})

        return sorted(all_cycles)

    def to_json(self):
        return {name: {'provides': sorted(provides), 'requires': sorted(requires)}
                for name, (provides, requires) in self._mods.items()}
