"""Parallel-capable state machine."""


class UnknownState(Exception):
    pass


class GuardFailed(Exception):
    pass


class NotParallel(Exception):
    pass


class Machine:
    def __init__(self, initial, states, on_transition=None):
        self.initial = initial
        self.states = states
        self.state = initial
        self.history = [initial]
        self.on_transition = on_transition
        self._open_regions = {}
        if self._is_parallel(initial):
            self._open_region(initial)

    # ------------------------------------------------------------------
    # helpers
    # ------------------------------------------------------------------

    def _is_parallel(self, state):
        defn = self.states.get(state)
        return isinstance(defn, dict) and 'parallel' in defn

    def _is_terminal(self, state):
        defn = self.states.get(state)
        return isinstance(defn, list) and len(defn) == 0

    def _find_transition(self, src, target):
        defn = self.states.get(src)
        if defn is None:
            return None
        if isinstance(defn, dict) and 'parallel' in defn:
            if target in defn['parallel']:
                return {'to': target}
            return None
        if isinstance(defn, list):
            for t in defn:
                if isinstance(t, dict):
                    if t.get('to') == target:
                        return t
                elif t == target:
                    return {'to': target}
            return None
        return None

    def _compute_branch_path(self, branch):
        path = set()
        queue = [branch]
        while queue:
            s = queue.pop(0)
            if s in path:
                continue
            path.add(s)
            defn = self.states.get(s)
            if isinstance(defn, list):
                for t in defn:
                    if isinstance(t, dict):
                        queue.append(t['to'])
                    else:
                        queue.append(t)
        return path

    def _open_region(self, region):
        defn = self.states[region]
        branches = list(defn['parallel'])
        branch_paths = {b: self._compute_branch_path(b) for b in branches}
        self._open_regions[region] = {
            'branches': branches,
            'completed': set(),
            'members': {region},
            'branch_paths': branch_paths,
        }

    def _region_for(self, state):
        for region, info in self._open_regions.items():
            if state in info['members']:
                return region
        return None

    def _snapshot_regions(self):
        snap = {}
        for k, v in self._open_regions.items():
            snap[k] = {
                'branches': list(v['branches']),
                'completed': set(v['completed']),
                'members': set(v['members']),
                'branch_paths': {b: set(p) for b, p in v['branch_paths'].items()},
            }
        return snap

    # ------------------------------------------------------------------
    # public API
    # ------------------------------------------------------------------

    def go(self, target, **ctx):
        if target not in self.states:
            raise UnknownState(target)

        src = self.state
        transition = self._find_transition(src, target)
        region = self._region_for(src)

        if transition is None:
            if (region is not None
                    and target in self._open_regions[region]['branches']
                    and len(self._open_regions[region]['completed']) < len(self._open_regions[region]['branches'])):
                transition = {'to': target}
            else:
                raise UnknownState(target)

        # guard
        guard = transition.get('guard')
        if guard is not None:
            if not guard(**ctx):
                raise GuardFailed(f"Guard failed: {src} -> {target}")

        # snapshot for rollback
        old_state = self.state
        old_history_len = len(self.history)
        old_regions = self._snapshot_regions()

        # apply state change
        self.state = target
        self.history.append(target)

        # region bookkeeping
        if self._is_parallel(target):
            self._open_region(target)
        elif region is not None:
            self._open_regions[region]['members'].add(target)
            if self._is_terminal(target):
                for branch in self._open_regions[region]['branches']:
                    if target in self._open_regions[region]['branch_paths'].get(branch, set()):
                        self._open_regions[region]['completed'].add(branch)

        # action
        action = transition.get('action')
        result = None
        if action is not None:
            try:
                result = action(target)
            except Exception:
                self.state = old_state
                self.history = self.history[:old_history_len]
                self._open_regions = old_regions
                raise

        # on_transition callback
        if self.on_transition is not None:
            self.on_transition(src, target)

        if result is not None:
            return result
        return target

    def join(self, name):
        if name not in self.states:
            raise NotParallel(name)
        if not self._is_parallel(name):
            raise NotParallel(name)
        if name not in self._open_regions:
            return False
        info = self._open_regions[name]
        return len(info['completed']) == len(info['branches'])
